/**
 * FFI 失败。
 *
 * 用 `enum` 而不是 struct：UniFFI 0.29 的 `#[derive(uniffi::Error)]` 只支持枚举
 * （`uniffi_macros::error::expand_error` 内部构造的是 `EnumItem`）。
 * 只有一个变体 `Failure`；Kotlin 侧生成的是 `FfiException.Failure(code, messageText, context)`
 * —— 类型名带 `Exception` 后缀是 UniFFI 的 Kotlin 命名规则。
 *
 * # 为什么字段是 `message_text` 而不是 `message`
 *
 * Kotlin 生成的 `Failure` 继承 `FfiException`，而它继承 `kotlin.Exception` → `Throwable`；
 * UniFFI 同时会给异常生成一个 `override val message` getter，那个 getter 又要引用记录里的同名字段
 * —— 同名冲突，实测编译器报：
 *
 * ```text
 * e: 'message' hides member of supertype 'Throwable' and needs an 'override' modifier
 * e: Conflicting declarations: val message: String
 * ```
 *
 * 所以字段改名为 `message_text`（Kotlin 侧自动转成 `messageText`）。**语义不变**：
 * 契约 §1 里那一格还是「§11 错误码短名」（如 `NO_PEER`），
 * 完整人话串由 `Throwable.message` 给出（`1002 NO_PEER: no such peer session`）。
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * 统一失败形态。
     *
     * - `code`：`docs/03-protocol.md` §11 错误码的数值形式（如 `1002` = `NO_PEER`）；
     * - `message_text`：错误码短名（如 `NO_PEER`），供日志 / UI 查找与展示；
     * - `context`：出错细节（谁、在哪、什么值）。
     */
    class Failure(
        
        /**
         * §11 错误码数值。
         */
        val `code`: kotlin.UShort, 
        
        /**
         * §11 错误码短名。
         */
        val `messageText`: kotlin.String, 
        
        /**
         * 失败细节。
         */
        val `context`: kotlin.String
        ) : FfiException() {
        override val message
            get() = "code=${ `code` }, messageText=${ `messageText` }, context=${ `context` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Failure(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`messageText`)
                + FfiConverterString.allocationSize(value.`context`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Failure -> {
                buf.putInt(1)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`messageText`, buf)
                FfiConverterString.write(value.`context`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





